import { createHash, timingSafeEqual } from "node:crypto";
import handler from "vinext/server/fetch-handler";
import { runJobs, pendingJobs } from "../lib/server/jobs";
import { kickRunner } from "../lib/server/runner";
import { cleanup } from "../lib/server/retention";

export { GenerationRunner } from "../lib/server/runner";

/**
 * Cron heartbeat. Portraits are generated by the GenerationRunner Durable Object, which payment starts
 * directly. The heartbeat reclaims stale jobs and escalates unpaid or unconfigured ones (a short runJobs
 * pass never starts a chargeable call), then wakes the runner if work is waiting. Without the runner
 * binding (local tools), the minute cron processes the queue itself with a long deadline.
 */
async function heartbeat(minutely: boolean) {
  await runJobs();
  if (!(await pendingJobs())) return;
  if (await kickRunner()) return;
  if (minutely) await runJobs(Date.now() + 13 * 60_000);
}

const headers = { "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" };
function authorized(request: Request, env: Cloudflare.Env) {
  const supplied = request.headers.get("X-NOOR-Gateway-Token") ?? "";
  const expected = env.GATEWAY_TOKEN;
  if (!expected || !supplied) return false;
  const digest = (value: string) => createHash("sha256").update(value).digest();
  return timingSafeEqual(digest(supplied), digest(expected));
}

export default {
  async scheduled(event: ScheduledController, _env: Cloudflare.Env, ctx: ExecutionContext) {
    // Both schedules are a heartbeat for the generation runner; the hourly one (and manual test triggers)
    // also runs retention cleanup.
    const minutely = event.cron === "* * * * *";
    const work = minutely ? heartbeat(true) : Promise.all([cleanup(), heartbeat(false)]);
    ctx.waitUntil(work.then(() => {
      console.log(JSON.stringify({ event: "noor_scheduled_complete", cron: event.cron, scheduledTime: event.scheduledTime }));
    }));
  },
  async fetch(request: Request, env: Cloudflare.Env, ctx: ExecutionContext) {
    const path = new URL(request.url).pathname;
    if (request.method === "GET" && path === "/api/health") {
      return Response.json({ ok: true }, { headers });
    }
    if (!authorized(request, env)) {
      return Response.json({ error: "unauthorized" }, { status: 401, headers });
    }
    const response = await handler.fetch(request, env, ctx);
    if (request.method === "POST" && path.startsWith("/api/")) ctx.waitUntil(runJobs());
    return response;
  },
};
